QJsonObject EtfMonitorPage::filters()const{auto choice=sort->currentData().toString();return {{"search",search->text()},{"availability",availability->currentData().toString()},{"sort",choice.section('-',0,0)},{"ascending",choice.endsWith("-asc")}};}
QJsonObject EtfMonitorPage::selectedItem()const{for(auto v:current.value("items").toArray())if(v.toObject().value("id")==selected)return v.toObject();return {};}
void EtfMonitorPage::historyOptions(){updating=true;history->clear();history->addItem("当前观测","");auto fs=archive.value("frames").toArray();for(int n=int(fs.size())-1;n>=0;n--){auto f=fs[n].toObject();history->addItem("保存于 "+f.value("storedAt").toString(),f.value("id").toString());}int pos=history->findData(historical);history->setCurrentIndex(pos<0?0:pos);updating=false;}
void EtfMonitorPage::render(bool reset){if(reset){page=0;selected.clear();}auto visible=etfMonitor::rows(current,filters());page=qBound(0,page,qMax(0,(int(visible.size())-1)/24));updating=true;list->clear();int chosen=-1;for(int n=page*24;n<visible.size()&&n<(page+1)*24;n++){auto r=visible[n].toObject(),q=r.value("quote").toObject();auto item=new QListWidgetItem(r.value("name").toString()+" · "+r.value("id").toString().section(':',2)+"\n价格 "+value(q.value("price"))+"；涨幅% "+value(q.value("changePercent"),2)+"；成交额元 "+value(q.value("amount"),2),list);item->setToolTip(r.value("id").toString()+"\n"+q["sourceTime"].toString());if(q["changePercent"].isDouble()&&q["changePercent"].toDouble()!=0)item->setForeground(q["changePercent"].toDouble()>0?appearance::theme(window()->property("stockTheme").toString()).up:appearance::theme(window()->property("stockTheme").toString()).down);item->setData(Qt::UserRole,r.value("id"));item->setSizeHint(QSize(0,58));if(r.value("id")==selected)chosen=list->count()-1;}if(chosen<0&&list->count()>0)chosen=0;list->setCurrentRow(chosen);selected=chosen>=0?list->item(chosen)->data(Qt::UserRole).toString():QString();updating=false;pager->setText(QString("%1/%2 · %3").arg(page+1).arg(qMax(1,(int(visible.size())+23)/24)).arg(visible.size()));previous->setEnabled(page>0);next->setEnabled((page+1)*24<visible.size());select();}
void EtfMonitorPage::select(){auto r=selectedItem();auto quote=r["quote"].toObject(),momentum=r["momentum"].toObject();auto theme=appearance::theme(window()->property("stockTheme").toString());auto sign=quote["changePercent"].isDouble()?quote["changePercent"].toDouble():0.;auto color=sign>0?theme.up:sign<0?theme.down:theme.text;QString info=r.isEmpty()?QString("<h3>暂无匹配的ETF</h3>"):QString("<h2>%1 · %2</h2><p style='font-size:24px;color:%3'>%4 &nbsp; %5%</p><p>报价时间 %6</p><table cellpadding='8'><tr><td>成交额</td><td>%7 元</td></tr><tr><td>末5分钟成交额</td><td>%8 元</td></tr><tr><td>5分钟环比</td><td>%9%</td></tr></table><p>%10</p>").arg(r["name"].toString().toHtmlEscaped(),r["id"].toString().section(':',2),color.name(),value(quote["price"]),value(quote["changePercent"],2),quote["sourceTime"].toString("未取得").toHtmlEscaped(),value(quote["amount"],2),value(momentum["rolling5AmountYuan"],2),value(momentum["rolling5ChangePct"],2),quote["error"].toString().toHtmlEscaped());detail->setHtml(info);QJsonArray plotPoints;QString day;for(auto v:r["minuteInput"].toObject()["rows"].toArray()){auto row=v.toObject();if(!row["valid"].toBool()||!row["price"].isDouble())continue;auto at=QDateTime::fromMSecsSinceEpoch(qint64(row["time"].toDouble())).toOffsetFromUtc(28800);auto date=at.date().toString(Qt::ISODate);if(date>day){day=date;plotPoints={};}if(date==day)plotPoints.append(QJsonObject{{"label",at.toString("HH:mm")},{"price",row["price"]}});}auto minuteFrame=marketComparison::leadingFrame({{"status","available"},{"points",plotPoints},{"priceLabel","价格"},{"name",day+" · 1分钟"}});minuteFrame["viewScope"]=QString::fromUtf8(QJsonDocument(QJsonObject{{"id",r["id"]},{"observation",historical.isEmpty()?QString("current"):historical},{"period","minute"}}).toJson(QJsonDocument::Compact));minuteFrame["tradingDate"]=day;minutePlot->setFrame(minuteFrame,true);raw->setPlainText(r.isEmpty()?QString():QString::fromUtf8(QJsonDocument(r).toJson(QJsonDocument::Indented)));open->setEnabled(active&&!r.isEmpty());refreshQuotes->setEnabled(active&&refreshAvailable&&token.isEmpty()&&list->count()>0);refreshMinute->setEnabled(active&&refreshAvailable&&token.isEmpty()&&!r.isEmpty());stop->setEnabled(!token.isEmpty());}
void EtfMonitorPage::request(QString mode,bool automated){if(!active||!refreshAvailable||!token.isEmpty())return;QJsonArray ids;if(mode=="minute"){if(selected.isEmpty())return;ids.append(selected);}else for(int n=0;n<list->count();n++)ids.append(list->item(n)->data(Qt::UserRole).toString());if(ids.isEmpty())return;automaticRequest=automated;if(isVisible()&&!automatic->isActive())automatic->start(marketRefresh::chinaInterval(QDateTime::currentDateTimeUtc(),refreshFailures));token=QUuid::createUuid().toString(QUuid::WithoutBraces);select();message->setText("正在更新所选ETF…");emit refreshRequested(token,{{"ids",ids},{"period",mode}});}
void EtfMonitorPage::storeSnapshot(const QJsonObject& input){auto safe=etfMonitor::snapshot(input);auto next=etfMonitor::append(archive,safe,now());store.save(next,archive.value("revision").toDouble());archive=next;current=safe;historical.clear();historyOptions();render();message->setText("已载入观测数据 · 日期和时点见各项，不代表实时更新");}
void EtfMonitorPage::setSnapshot(const QJsonObject& input){if(!active)return;cancel();try{storeSnapshot(input);}catch(...){setHostError({});}}
void EtfMonitorPage::acceptSnapshot(const QString& incoming,const QJsonObject& input,const QString& warning){if(!active||token.isEmpty()||token!=incoming)return;try{if(automaticRequest){current=etfMonitor::snapshot(input);render();message->setText("已接收来源响应 · 是否推进以各项来源时点为准");}else storeSnapshot(input);automaticRequest=false;refreshFailures=warning.isEmpty()?0:std::min(3,refreshFailures+1);automatic->setInterval(marketRefresh::chinaInterval(QDateTime::currentDateTimeUtc(),refreshFailures));if(!warning.isEmpty())attempt("failed",warning);token.clear();select();if(!warning.isEmpty())message->setText("部分请求失败："+warning+"；失败项保留此前数据");}catch(...){failRefresh(incoming,"ETF输入/缓存检查失败");}}
void EtfMonitorPage::attempt(QString status,QString reason){try{auto next=etfMonitor::failed(archive,status,now(),reason);store.save(next,archive.value("revision").toDouble());archive=next;historyOptions();}catch(...){setHostError({});}}
void EtfMonitorPage::failRefresh(const QString& incoming,const QString& reason){if(token.isEmpty()||token!=incoming)return;token.clear();refreshFailures=std::min(3,refreshFailures+1);automatic->setInterval(marketRefresh::chinaInterval(QDateTime::currentDateTimeUtc(),refreshFailures));attempt("failed",reason);select();message->setText("刷新未完成："+reason+"；保留此前数据");}
void EtfMonitorPage::cancel(){if(automatic)automatic->stop();if(token.isEmpty())return;auto prior=token;token.clear();emit cancelRefreshRequested(prior);attempt("cancelled","用户取消；迟到结果不保存");select();message->setText("已取消更新");}
void EtfMonitorPage::setActive(bool on){if(!on)cancel();active=on;select();if(on&&refreshAvailable&&isVisible()&&!automatic->isActive())automatic->start(180);}
void EtfMonitorPage::setRefreshAvailable(bool available){refreshAvailable=available;select();if(!available)automatic->stop();else if(active&&isVisible()&&!automatic->isActive())automatic->start(180);}
QJsonObject EtfMonitorPage::saveState()const{auto f=filters();if(QRegularExpression("(?i)(sk-|bearer|api[_-]?key|password|authorization|token[=:])").match(f.value("search").toString()).hasMatch())f["search"]="";return {{"schema","native-etf-monitor-ui/v1"},{"filters",f},{"selected",selected},{"history",historical},{"period",period->currentData().toString()},{"page",page},{"minuteViewport",minutePlot->saveViewport()}};}
void EtfMonitorPage::restoreState(const QJsonObject& s){if(s.value("schema")!="native-etf-monitor-ui/v1")return;updating=true;auto f=s.value("filters").toObject();QString choice=f.value("sort").toString()+"-"+(f.value("ascending").toBool()?"asc":"desc");int n=sort->findData(choice);sort->setCurrentIndex(n<0?0:n);n=availability->findData(f.value("availability").toString());availability->setCurrentIndex(n<0?0:n);search->setText(f.value("search").toString().left(120));n=period->findData(s.value("period").toString());period->setCurrentIndex(n<0?0:n);historical=s.value("history").toString();if(history->findData(historical)<0)historical.clear();try{current=etfMonitor::frame(archive,historical);}catch(...){historical.clear();}history->setCurrentIndex(qMax(0,history->findData(historical)));selected=s.value("selected").toString();page=qBound(0,s.value("page").toInt(),83);updating=false;render();minutePlot->restoreViewport(s["minuteViewport"].toObject());}
QByteArray EtfMonitorPage::exportEvidence()const{auto out=current;out["items"]=etfMonitor::rows(current,filters());out["moduleAttempt"]=archive.value("attempt");out["exportedAt"]=now();out["historicalFrame"]=historical;return QJsonDocument(out).toJson(QJsonDocument::Indented);}
void EtfMonitorPage::refreshAppearance(){auto viewport=minutePlot->saveViewport();render();minutePlot->restoreViewport(viewport);}
void EtfMonitorPage::showEvent(QShowEvent* event){QWidget::showEvent(event);if(active&&refreshAvailable)automatic->start(180);}
void EtfMonitorPage::hideEvent(QHideEvent* event){cancel();QWidget::hideEvent(event);}
void EtfMonitorPage::setHostError(const QString&){message->setText("ETF数据检查未通过；此前观测已保留");}
